import React from 'react'

export type LayoutContentContextValue = {
  headerNode: HTMLDivElement | null
  headerRef: React.RefObject<HTMLDivElement | null>
  footerNode: HTMLDivElement | null
  footerRef: React.RefObject<HTMLDivElement | null>
  titleText: string
  titleTextRef: React.RefObject<string>
}

const LayoutContentContext = React.createContext<LayoutContentContextValue | null>(null)

export function LayoutContentProvider({
  value,
  children,
}: React.PropsWithChildren<{ value: LayoutContentContextValue }>) {
  return <LayoutContentContext.Provider value={value}>{children}</LayoutContentContext.Provider>
}

export function useLayoutContentContext() {
  const value = React.useContext(LayoutContentContext)

  if (!value) {
    throw new Error('useLayoutContentContext must be used within LayoutContentProvider')
  }

  return value
}

import { useMemo } from 'react'
// Localization is intentionally disabled for the formal host shell, so the locale switcher stays hidden and visible copy remains literal.

type TranslationParams = Record<string, string | number | boolean | null | undefined>
type LocaleDirection = 'ltr' | 'rtl'
type LocaleOption = { id: string; nativeLabel: string }

const DEFAULT_LOCALE = 'zh-CN'

function resolveLocale() {
  if (typeof document !== 'undefined') {
    const documentLocale = String(document.documentElement.lang || '').trim()
    if (documentLocale) return documentLocale
  }
  if (typeof navigator !== 'undefined') {
    const navigatorLocale = String(navigator.language || '').trim()
    if (navigatorLocale) return navigatorLocale
  }
  return DEFAULT_LOCALE
}

function resolveDirection(locale: string): LocaleDirection {
  if (typeof document !== 'undefined') {
    return document.documentElement.dir === 'rtl' ? 'rtl' : 'ltr'
  }
  return String(locale || '').toLowerCase().startsWith('ar') ? 'rtl' : 'ltr'
}

function interpolate(template: string, params?: TranslationParams) {
  if (!params) return template
  return template.replace(/\{(\w+)\}/g, (_, key: string) => {
    const value = params[key]
    return value == null ? '' : String(value)
  })
}

export function useHostShellLocalization() {
  return useMemo(() => {
    const locale = resolveLocale()
    return {
      dir: resolveDirection(locale),
      locale,
      setLocale: (nextLocale?: string) => String(nextLocale || locale),
      t: (key: string, params?: TranslationParams) => interpolate(key, params),
      localeSwitcherEnabled: false,
      localeOptions: [] as LocaleOption[],
      languageFieldLabel: 'Language',
      userCenterLabel: '用户中心',
    }
  }, [])
}

import React from 'react'
import { TypicalPageHostProvider } from '../../../components/hiui-design-runtime/host'
import { HostPageFooterPortal } from './page-header-portal'

type TypicalPageHostBridgeProps = React.PropsWithChildren<{
  getOverlayContainer?: () => HTMLElement | null
}>

export function TypicalPageHostBridge({
  children,
  getOverlayContainer,
}: TypicalPageHostBridgeProps) {
  return (
    <TypicalPageHostProvider
      footerPortal={HostPageFooterPortal}
      getOverlayContainer={getOverlayContainer}
    >
      {children}
    </TypicalPageHostProvider>
  )
}

function normalizeRoutePath(path: string | undefined) {
  if (!path) return ''
  if (path === '/') return '/'

  return String(path).replace(/\/+/g, '/').replace(/^\/+|\/+$/g, '')
}

function normalizeLocationPath(path: string | undefined) {
  const normalized = normalizeRoutePath(path)
  return normalized || '/'
}

function joinRoutePath(parentPath: string | undefined, routePath: string | undefined) {
  const parent = normalizeRoutePath(parentPath)
  const seg = normalizeRoutePath(routePath)

  if (seg === '/') return parent || '/'
  if (!parent || parent === '/') return seg || parent
  if (!seg) return parent

  return `${parent}/${seg}`
}

export function stripRouteBasePath(pathname: string | undefined, routeBasePath = '') {
  const normalizedPath = normalizeLocationPath(pathname)
  const normalizedBase = normalizeRoutePath(routeBasePath)

  if (!normalizedBase || normalizedBase === '/') return normalizedPath
  if (normalizedPath === normalizedBase) return '/'
  if (normalizedPath.startsWith(`${normalizedBase}/`)) {
    return normalizedPath.slice(normalizedBase.length + 1) || '/'
  }

  return normalizedPath
}

export function buildNavigationPath(path: string | undefined, routeBasePath = '') {
  const normalizedPath = normalizeLocationPath(path)
  const normalizedBase = normalizeRoutePath(routeBasePath)

  if (!normalizedBase || normalizedBase === '/') {
    return normalizedPath === '/' ? '/' : `/${normalizedPath}`
  }

  if (normalizedPath === '/') {
    return `/${normalizedBase}`
  }

  return `/${joinRoutePath(normalizedBase, normalizedPath)}`
}

